// Only react when assignment or status actually changed, so routine conversation updates
// never cancel a pause the n8n bot set itself (its 12h handoff).
const b = $input.first().json.body || {};
const ev = b.event;
if (!['conversation_updated', 'conversation_status_changed', 'conversation_created'].includes(ev)) return [];
const ca = b.changed_attributes;
const changed = Array.isArray(ca) ? ca.flatMap(o => Object.keys(o || {})) : Object.keys(ca || {});
const relevant = ev !== 'conversation_updated' || changed.some(k => ['assignee_id', 'status', 'team_id'].includes(k));
if (!relevant || !b.id) return [];
return [{ json: { event: ev, conversationId: b.id, changed } }];

// Decide from Chatwoot's API answer (not the webhook payload): a human assignee on an open
// conversation pauses the n8n bot for that WhatsApp chat; unassigned or resolved resumes it.
const INBOX_ID = 'REPLACE_WITH_INBOX_ID'; // Chatwoot API-channel inbox used by the OpenWA adapter
const r = $input.first().json;
if (r.statusCode !== 200) throw new Error(`Chatwoot API answered ${r.statusCode} for conversation ${$('Keep Assignment Changes').first().json.conversationId}`);
const c = r.body || {};
if (/^\d+$/.test(INBOX_ID) && String(c.inbox_id) !== INBOX_ID) return [];
const sender = (c.meta && c.meta.sender) || {};
const assignee = c.meta && c.meta.assignee;
const human = !!(assignee && assignee.id) && c.status !== 'resolved';
const ids = new Set();
if (sender.identifier && /@(c\.us|s\.whatsapp\.net|lid)$/.test(sender.identifier)) ids.add(sender.identifier);
const digits = String(sender.phone_number || '').replace(/\D/g, '');
if (digits.length >= 10) ids.add(`${digits}@c.us`);
if (!ids.size) return [];
const until = human ? new Date(Date.now() + 30 * 86400e3).toISOString() : '';
const now = new Date().toISOString();
return [...ids].map(chat_id => ({ json: {
  chat_id, paused_until: until, updated_at: now,
  note: human ? `assigned to ${assignee.name || assignee.id} in Chatwoot (#${c.id})` : `released in Chatwoot (#${c.id}, ${c.status})`,
}, pairedItem: { item: 0 } }));
